func progName() string {
	return filepath.Base(os.Args[0])
}

func printHelp() {
	t := helpText
	// replace executable with actual prog name
	t = strings.ReplaceAll(t, "executable", progName())
	fmt.Fprint(os.Stdout, t)
	if !strings.HasSuffix(t, "\n") {
		fmt.Fprint(os.Stdout, "\n")
	}
}

func printVersion() {
	fmt.Fprintln(os.Stdout, versionStr)
}

func clapError(msg string) {
	fmt.Fprintln(os.Stderr, msg)
	fmt.Fprintln(os.Stderr, "")
	// For some errors, usage is dynamic; for simplicity use static unless missing URL/conflict?
	// Caller should have already printed usage? We'll handle in callers.
}

func failInvalidValue(flag, value, detail string) {
	// flag like "-n <N_REQUESTS>" or "--output-format <OUTPUT_FORMAT>"
	// detail may include possible values on next line
	if strings.Contains(detail, "[possible values") {
		fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '%s'\n  %s\n\nFor more information, try '--help'.\n", value, flag, detail)
	} else {
		fmt.Fprintf(os.Stderr, "error: invalid value '%s' for '%s': %s\n\nFor more information, try '--help'.\n", value, flag, detail)
	}
	os.Exit(2)
}

func failMissingValue(flag string, possible string) {
	if possible != "" {
		fmt.Fprintf(os.Stderr, "error: a value is required for '%s' but none was supplied\n  %s\n\nFor more information, try '--help'.\n", flag, possible)
	} else {
		fmt.Fprintf(os.Stderr, "error: a value is required for '%s' but none was supplied\n\nFor more information, try '--help'.\n", flag)
	}
	os.Exit(2)
}

func failUnexpectedArg(arg string) {
	if strings.HasPrefix(arg, "-") {
		fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\n  tip: to pass '%s' as a value, use '-- %s'\n\nUsage: %s [OPTIONS] <URL>\n\nFor more information, try '--help'.\n", arg, arg, arg, progName())
	} else {
		fmt.Fprintf(os.Stderr, "error: unexpected argument '%s' found\n\nUsage: %s [OPTIONS] <URL>\n\nFor more information, try '--help'.\n", arg, progName())
	}
	os.Exit(2)
}

func failMissingURL(provided []string) {
	fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  <URL>\n\nUsage: %s", progName())
	if len(provided) > 0 {
		for _, p := range provided {
			fmt.Fprintf(os.Stderr, " %s", p)
		}
	} else {
		fmt.Fprintf(os.Stderr, " [OPTIONS]")
	}
	fmt.Fprintf(os.Stderr, " <URL>\n\nFor more information, try '--help'.\n")
	os.Exit(2)
}

func failConflict(a, b string, provided []string) {
	fmt.Fprintf(os.Stderr, "error: the argument '%s' cannot be used with '%s'\n\nUsage: %s", a, b, progName())
	if len(provided) > 0 {
		for _, p := range provided {
			fmt.Fprintf(os.Stderr, " %s", p)
		}
	} else {
		fmt.Fprintf(os.Stderr, " [OPTIONS]")
	}
	fmt.Fprintf(os.Stderr, " <URL>\n\nFor more information, try '--help'.\n")
	os.Exit(2)
}

func failMultiple(flag string) {
	fmt.Fprintf(os.Stderr, "error: the argument '%s' cannot be used multiple times\n\nUsage: %s [OPTIONS] <URL>\n\nFor more information, try '--help'.\n", flag, progName())
	os.Exit(2)
}

func failRequiredMissing(flag string, provided []string) {
	fmt.Fprintf(os.Stderr, "error: the following required arguments were not provided:\n  %s\n\nUsage: %s", flag, progName())
	if len(provided) > 0 {
		for _, p := range provided {
			fmt.Fprintf(os.Stderr, " %s", p)
		}
	} else {
		fmt.Fprintf(os.Stderr, " [OPTIONS]")
	}
	fmt.Fprintf(os.Stderr, " <URL>\n\nFor more information, try '--help'.\n")
	os.Exit(2)
}

func runtimeError(msg string) {
	fmt.Fprintf(os.Stderr, "Error: %s\n", msg)
	os.Exit(1)
}

