// canonical usage strings for flags (for dynamic usage)
func canonicalUsage(field string) string {
	switch field {
	case "n": return "-n <N_REQUESTS>"
	case "c": return "-c <N_CONNECTIONS>"
	case "p": return "-p <N_HTTP2_PARALLEL>"
	case "z": return "-z <DURATION>"
	case "w": return "--wait-ongoing-requests-after-deadline"
	case "q": return "-q <QUERY_PER_SECOND>"
	case "burst-delay": return "--burst-delay <BURST_DURATION>"
	case "burst-rate": return "--burst-rate <BURST_REQUESTS>"
	case "rand-regex-url": return "--rand-regex-url"
	case "urls-from-file": return "--urls-from-file"
	case "max-repeat": return "--max-repeat <MAX_REPEAT>"
	case "dump-urls": return "--dump-urls <DUMP_URLS>"
	case "latency-correction": return "--latency-correction"
	case "no-tui": return "--no-tui"
	case "fps": return "--fps <FPS>"
	case "method": return "--method <METHOD>"
	case "H": return "-H <HEADERS>"
	case "proxy-header": return "--proxy-header <PROXY_HEADERS>"
	case "timeout": return "-t <TIMEOUT>"
	case "connect-timeout": return "--connect-timeout <CONNECT_TIMEOUT>"
	case "A": return "-A <ACCEPT_HEADER>"
	case "d": return "-d <BODY_STRING>"
	case "D": return "-D <BODY_PATH>"
	case "Z": return "-Z <BODY_PATH_LINES>"
	case "form": return "--form <FORM>"
	case "T": return "-T <CONTENT_TYPE>"
	case "a": return "-a <BASIC_AUTH>"
	case "aws-session": return "--aws-session <AWS_SESSION>"
	case "aws-sigv4": return "--aws-sigv4 <AWS_SIGV4>"
	case "x": return "-x <PROXY>"
	case "proxy-http-version": return "--proxy-http-version <PROXY_HTTP_VERSION>"
	case "proxy-http2": return "--proxy-http2"
	case "http-version": return "--http-version <HTTP_VERSION>"
	case "http2": return "--http2"
	case "host": return "--host <HOST>"
	case "disable-compression": return "--disable-compression"
	case "redirect": return "--redirect <REDIRECT>"
	case "disable-keepalive": return "--disable-keepalive"
	case "no-pre-lookup": return "--no-pre-lookup"
	case "ipv6": return "--ipv6"
	case "ipv4": return "--ipv4"
	case "cacert": return "--cacert <CACERT>"
	case "cert": return "--cert <CERT>"
	case "key": return "--key <KEY>"
	case "insecure": return "--insecure"
	case "connect-to": return "--connect-to <CONNECT_TO>"
	case "no-color": return "--no-color"
	case "unix-socket": return "--unix-socket <UNIX_SOCKET>"
	case "stats-breakdown": return "--stats-success-breakdown"
	case "db-url": return "--db-url <DB_URL>"
	case "debug": return "--debug"
	case "output": return "--output <OUTPUT>"
	case "output-format": return "--output-format <OUTPUT_FORMAT>"
	case "time-unit": return "--time-unit <TIME_UNIT>"
	}
	return field
}

func (c *Config) markProvided(field string) {
	if c.providedSet == nil { c.providedSet = map[string]bool{} }
	u := canonicalUsage(field)
	if !c.providedSet[u] {
		c.providedSet[u] = true
		c.providedOrder = append(c.providedOrder, u)
	}
}

func parseNRequests(s string) (int, error) {
	if s == "" {
		return 0, fmt.Errorf("cannot parse integer from empty string")
	}
	lower := strings.ToLower(s)
	mult := 1.0
	numStr := s
	if strings.HasSuffix(lower, "k") {
		numStr = s[:len(s)-1]
		mult = 1000
	} else if strings.HasSuffix(lower, "m") {
		numStr = s[:len(s)-1]
		mult = 1000000
	}
	if numStr == "" {
		return 0, fmt.Errorf("cannot parse integer from empty string")
	}
	// If suffix present, parse as float then multiply
	if mult != 1.0 {
		f, err := strconv.ParseFloat(numStr, 64)
		if err != nil {
			// distinguish invalid float vs digit?
