	}
	if hasBPath && hasBLines {
		failConflict("-D <BODY_PATH>", "-Z <BODY_PATH_LINES>", cfg.providedOrder)
	}
	if hasForm && hasD {
		failConflict("--form <FORM>", "-d <BODY_STRING>", cfg.providedOrder)
