		} else {
			fmt.Fprintf(os.Stderr, " [OPTIONS]")
		}
		fmt.Fprintf(os.Stderr, " <URL>\n\nFor more information, try '--help'.\n")
		os.Exit(2)
	}
	// http2 vs http-version exclusive is runtime Error, not clap. Handle later in main.
	// proxy-http2 vs proxy-http-version similarly runtime.

	return cfg
}

