				out.WriteByte(template[i])
				i++
				continue
			}
			j += i
			classStr := template[i+1 : j]
			// parse quantifier after ]
			k := j + 1
			repMin, repMax := 1, 1
			hasQuant := false
			if k < len(template) {
				if template[k] == '*' {
					repMin, repMax = 0, maxRepeat
					hasQuant = true
					k++
				} else if template[k] == '+' {
					repMin, repMax = 1, maxRepeat+1
