							aStr := strings.TrimSpace(parts[0])
							bStr := strings.TrimSpace(parts[1])
							if aStr == "" && bStr != "" {
								n, err := strconv.Atoi(bStr)
								if err == nil {
									repMin, repMax = 0, n
									hasQuant = true
									k = end + 1
								}
