func timeUnitDiv(unit string) (float64, string) {
	switch unit {
	case "ns": return float64(time.Second) / 1e9, "ns"
	case "us": return float64(time.Second) / 1e6, "us"
	case "ms": return float64(time.Second) / 1e3, "ms"
	case "s": return float64(time.Second), "sec"
	case "m": return float64(time.Minute), "min"
	case "h": return float64(time.Hour), "hr"
	}
	return float64(time.Millisecond), "ms"
}

func autoUnit(slowestSec float64) string {
	if math.IsNaN(slowestSec) || math.IsInf(slowestSec, 0) {
		return "ns"
	}
	if slowestSec < 1e-6 {
		return "ns"
	} else if slowestSec < 1e-3 {
		return "us"
	} else if slowestSec < 1 {
		return "ms"
	} else if slowestSec < 60 {
		return "s"
	} else if slowestSec < 3600 {
		return "m"
	} else {
		return "h"
	}
}

func formatTimeVal(sec float64, unit string, decimals int) string {
	if math.IsNaN(sec) {
		_, label := timeUnitDiv(unit)
		return fmt.Sprintf("NaN %s", label)
	}
	if math.IsInf(sec, 1) {
		_, label := timeUnitDiv(unit)
		return fmt.Sprintf("inf %s", label)
	}
	if math.IsInf(sec, -1) {
		_, label := timeUnitDiv(unit)
		return fmt.Sprintf("-inf %s", label)
	}
	div, label := timeUnitDiv(unit)
	v := sec * float64(time.Second) / div
	// div is duration in ns? Actually timeUnitDiv returns float64(time.Second)/... Hmm simpler: convert
	// Let's compute directly
	var conv float64
	switch unit {
	case "ns": conv = sec * 1e9
	case "us": conv = sec * 1e6
	case "ms": conv = sec * 1e3
	case "s": conv = sec
	case "m": conv = sec / 60
	case "h": conv = sec / 3600
	}
	_ = v
	format := fmt.Sprintf("%%.%df %%s", decimals)
	return fmt.Sprintf(format, conv, label)
}

