func percentile(sorted []float64, p float64) float64 {
	if len(sorted) == 0 {
		return math.NaN()
	}
	// nearest-rank: ceil(p/100 * n) -1
	n := len(sorted)
	k := int(math.Ceil(p/100*float64(n))) - 1
	if k < 0 { k = 0 }
	if k >= n { k = n-1 }
	return sorted[k]
}

