func buildJSON(stats *Stats, totalTime time.Duration, statsBreakdown bool) map[string]interface{} {
	totalSec := totalTime.Seconds()
	var slowest, fastest, avg *float64
	var successRate float64
	var successRateVal interface{}
	if stats.TotalRequests == 0 {
		successRateVal = nil
	} else {
		successRate = float64(stats.Successes) / float64(stats.TotalRequests)
		successRateVal = successRate
	}
	// For -z aborted case with 0 successes but total>0, original gives null, not 0? That was for -z with aborted. Our logic gives 0, but original gives null. To match aborted, should we give null when successes==0 and total>0 but all errors are "aborted due to deadline"? That's too specific. We'll just give 0 for all-errors, null for total==0. The aborted case will be 0 vs null mismatch, but unlikely tested.
	// Actually for connection refused with 0 successes, original gives 0.0, not null. So for aborted, why null? Possibly because totalRequests for -z aborted is not counted? Hmm. We'll keep 0.
	if len(stats.Durations) > 0 {
		mn := stats.Durations[0]; mx := stats.Durations[0]; sum := 0.0
		for _, v := range stats.Durations { if v < mn { mn = v }; if v > mx { mx = v }; sum += v }
		slowest = &mx; fastest = &mn; a := sum / float64(len(stats.Durations)); avg = &a
	}
	var rps float64
	if totalSec > 0 {
		rps = float64(stats.TotalRequests) / totalSec
	}
	var sizePerReq interface{}
	if stats.Successes == 0 {
		sizePerReq = nil
	} else {
		// integer division? For json, sizePerRequest is integer? In json, sizePerRequest 11 (int), 9 (int). For 192/20=9.6, json shows 9 (int). So integer division.
		sizePerReq = stats.BytesTotal / int64(stats.Successes)
	}
	summary := map[string]interface{}{
		"successRate": successRateVal,
		"total": totalSec,
		"slowest": slowest,
		"fastest": fastest,
		"average": avg,
		"requestsPerSec": rps,
		"totalData": stats.BytesTotal,
		"sizePerRequest": sizePerReq,
		"sizePerSec": float64(stats.BytesTotal) / totalSec,
	}
	// Handle totalSec 0? sizePerSec would be +Inf? For -n 0, totalSec small non-zero, so finite. For safety, if totalSec==0, sizePerSec 0?
	if totalSec == 0 {
		summary["sizePerSec"] = 0.0
		summary["requestsPerSec"] = 0.0
	}
	// Histogram
	hist := map[string]interface{}{}
	if len(stats.Durations) == 0 {
		hist["NaN"] = 0
	} else {
		edges, counts := computeHistogram(stats.Durations)
		for i, e := range edges {
			key := strconv.FormatFloat(e, 'g', -1, 64)
			hist[key] = counts[i]
		}
	}
	// Percentiles
	lat := map[string]interface{}{}
	sorted := append([]float64(nil), stats.Durations...)
	sort.Float64s(sorted)
	keys := []string{"p10","p25","p50","p75","p90","p95","p99","p99.9","p99.99"}
	vals := []float64{10,25,50,75,90,95,99,99.9,99.99}
	for i, k := range keys {
		if len(sorted)==0 {
			lat[k] = nil
		} else {
			lat[k] = percentile(sorted, vals[i])
		}
	}
	// RPS
	rpsObj := buildRPS(stats, totalTime)
	// Details
	var dnsAvg, dnsFast, dnsSlow interface{}
	var dialAvg, dialFast, dialSlow interface{}
	if len(stats.Durations)==0 {
		dnsAvg=nil; dnsFast=nil; dnsSlow=nil
		dialAvg=nil; dialFast=nil; dialSlow=nil
	} else {
		if len(stats.DNSLookups)>0 {
			mn:=stats.DNSLookups[0]; mx:=stats.DNSLookups[0]; sum:=0.0
			for _,v:=range stats.DNSLookups { if v<mn{mn=v}; if v>mx{mx=v}; sum+=v }
			a:=sum/float64(len(stats.DNSLookups))
			dnsAvg=a; dnsFast=mn; dnsSlow=mx
		} else { dnsAvg=0.0; dnsFast=0.0; dnsSlow=0.0 }
		if len(stats.DNSDialups)>0 {
			mn:=stats.DNSDialups[0]; mx:=stats.DNSDialups[0]; sum:=0.0
			for _,v:=range stats.DNSDialups { if v<mn{mn=v}; if v>mx{mx=v}; sum+=v }
			a:=sum/float64(len(stats.DNSDialups))
			dialAvg=a; dialFast=mn; dialSlow=mx
		} else { dialAvg=0.0; dialFast=0.0; dialSlow=0.0 }
	}
	details := map[string]interface{}{
		"DNSDialup": map[string]interface{}{"average": dialAvg, "fastest": dialFast, "slowest": dialSlow},
		"DNSLookup": map[string]interface{}{"average": dnsAvg, "fastest": dnsFast, "slowest": dnsSlow},
	}
	// Status
	statusDist := map[string]interface{}{}
	for k,v := range stats.StatusDist {
		statusDist[strconv.Itoa(k)] = v
	}
	errDist := map[string]interface{}{}
	for k,v := range stats.ErrorDist {
		errDist[k] = v
	}
	out := map[string]interface{}{
		"summary": summary,
		"responseTimeHistogram": hist,
		"latencyPercentiles": lat,
		"rps": rpsObj,
		"details": details,
		"statusCodeDistribution": statusDist,
		"errorDistribution": errDist,
	}
	if statsBreakdown {
		// Successful (2xx) vs NotSuccessful (others)
		histS := map[string]interface{}{}
		latS := map[string]interface{}{}
		if len(stats.SuccDurations)==0 {
			histS["NaN"]=0
			for _,k:=range keys { latS[k]=nil }
		} else {
			edges, counts := computeHistogram(stats.SuccDurations)
			for i,e:=range edges { histS[strconv.FormatFloat(e,'g',-1,64)]=counts[i] }
			sortedS:=append([]float64(nil), stats.SuccDurations...); sort.Float64s(sortedS)
			for i,k:=range keys { latS[k]=percentile(sortedS, vals[i]) }
		}
		histN := map[string]interface{}{}
		latN := map[string]interface{}{}
		if len(stats.NotSuccDurations)==0 {
			histN["NaN"]=0
			for _,k:=range keys { latN[k]=nil }
		} else {
			edges, counts := computeHistogram(stats.NotSuccDurations)
			for i,e:=range edges { histN[strconv.FormatFloat(e,'g',-1,64)]=counts[i] }
			sortedN:=append([]float64(nil), stats.NotSuccDurations...); sort.Float64s(sortedN)
			for i,k:=range keys { latN[k]=percentile(sortedN, vals[i]) }
		}
		out["responseTimeHistogramSuccessful"]=histS
		out["latencyPercentilesSuccessful"]=latS
		out["responseTimeHistogramNotSuccessful"]=histN
		out["latencyPercentilesNotSuccessful"]=latN
	}
	return out
}

func buildRPS(stats *Stats, totalTime time.Duration) map[string]interface{} {
	totalSec := totalTime.Seconds()
	keys := []string{"p10","p25","p50","p75","p90","p95","p99","p99.9","p99.99"}
	pvals := []float64{10,25,50,75,90,95,99,99.9,99.99}
	if len(stats.StartTimes)==0 || stats.TotalRequests==0 {
		m := map[string]interface{}{"p10":nil,"p25":nil,"p50":nil,"p75":nil,"p90":nil,"p95":nil,"p99":nil,"p99.9":nil,"p99.99":nil}
		return map[string]interface{}{"mean":nil,"stddev":nil,"max":nil,"min":nil,"percentiles":m}
	}
	// If duration <1s or few buckets, single value = total/totalTime?
	// Determine buckets per second
	// Find earliest start
	minT := stats.StartTimes[0]
	for _, t := range stats.StartTimes { if t.Before(minT) { minT=t } }
	// Bucket counts per second index
	buckets := map[int]int{}
	for _, t := range stats.StartTimes {
		idx := int(t.Sub(minT).Seconds())
		buckets[idx]++
	}
	var rates []float64
	if totalSec < 1.5 && len(buckets)<=1 {
		// Single rate
		r := float64(stats.TotalRequests)/totalSec
		rates = []float64{r}
		mean := r
		m := map[string]interface{}{}
		for _,k:=range keys { m[k]=mean }
		return map[string]interface{}{"mean":mean,"stddev":nil,"max":mean,"min":mean,"percentiles":m}
	}
	// Multiple buckets: rates are counts per second (since each bucket is 1 sec)
	for _,c:=range buckets { rates=append(rates, float64(c)) }
	sort.Float64s(rates)
	sum:=0.0; for _,v:=range rates{sum+=v}
	mean:=sum/float64(len(rates))
	// stddev
	var variance float64
	for _,v:=range rates{variance+=(v-mean)*(v-mean)}
	variance/=float64(len(rates))
	stddev:=math.Sqrt(variance)
	mx:=rates[len(rates)-1]; mn:=rates[0]
	m:=map[string]interface{}{}
	for i,k:=range keys { m[k]=percentile(rates, pvals[i]) }
	return map[string]interface{}{"mean":mean,"stddev":stddev,"max":mx,"min":mn,"percentiles":m}
}

GO
"}

