func buildRPS(stats *Stats, totalTime time.Duration) map[string]interface{} {
	totalSec := totalTime.Seconds()
	keys := []string{"p10","p25","p50","p75","p90","p95","p99","p99.9","p99.99"}
	pvals := []float64{10,25,50,75,90,95,99,99.9,99.99}
