		m := map[string]interface{}{"p10":nil,"p25":nil,"p50":nil,"p75":nil,"p90":nil,"p95":nil,"p99":nil,"p99.9":nil,"p99.99":nil}
		return map[string]interface{}{"mean":nil,"stddev":nil,"max":nil,"min":nil,"percentiles":m}
	}
	// If duration <1s or few buckets, single value = total/totalTime?
	// Determine buckets per second
	// Find earliest start
	minT := stats.StartTimes[0]
	for _, t := range stats.StartTimes { if t.Before(minT) { minT=t } }
	// Bucket counts per second index
	buckets := map[int]int{}
	for _, t := range stats.StartTimes {
		idx := int(t.Sub(minT).Seconds())
		buckets[idx]++
	}
	var rates []float64
	if totalSec < 1.5 && len(buckets)<=1 {
		// Single rate
		r := float64(stats.TotalRequests)/totalSec
		rates = []float64{r}
		mean := r
		m := map[string]interface{}{}
		for _,k:=range keys { m[k]=mean }
		return map[string]interface{}{"mean":mean,"stddev":nil,"max":mean,"min":mean,"percentiles":m}
	}
	// Multiple buckets: rates are counts per second (since each bucket is 1 sec)
	for _,c:=range buckets { rates=append(rates, float64(c)) }
	sort.Float64s(rates)
	sum:=0.0; for _,v:=range rates{sum+=v}
	mean:=sum/float64(len(rates))
	// stddev
	var variance float64
	for _,v:=range rates{variance+=(v-mean)*(v-mean)}
	variance/=float64(len(rates))
	stddev:=math.Sqrt(variance)
	mx:=rates[len(rates)-1]; mn:=rates[0]
	m:=map[string]interface{}{}
	for i,k:=range keys { m[k]=percentile(rates, pvals[i]) }
	return map[string]interface{}{"mean":mean,"stddev":stddev,"max":mx,"min":mn,"percentiles":m}
