func mapError(err error) string {
	s := err.Error()
	ls := strings.ToLower(s)
	if strings.Contains(ls, "connection refused") {
		return "Connection refused (os error 111)"
	}
	if strings.Contains(ls, "no such file or directory") {
		return "No such file or directory (os error 2)"
	}
	if strings.Contains(ls, "network is unreachable") {
		// Original wraps as "proto error: io error: Network is unreachable (os error 101)"
		if strings.Contains(s, "proto") {
			return s
		}
		return "proto error: io error: Network is unreachable (os error 101)"
	}
	if strings.Contains(ls, "timeout") || strings.Contains(ls, "deadline exceeded") || strings.Contains(ls, "context deadline") {
		return "timeout"
	}
	if strings.Contains(ls, "too many redirects") || strings.Contains(ls, "stopped after") {
		return "Redirection limit has reached"
	}
	if strings.Contains(ls, "redirection limit") {
		return "Redirection limit has reached"
	}
	if strings.Contains(ls, "dispatch") {
		return "dispatch task is gone"
	}
	if strings.Contains(ls, "http2") {
		return "http2 error"
	}
	if strings.Contains(ls, "unsupported protocol scheme") {
		// For ftp etc, original gave network unreachable? We'll just return as is? To match ftp case which gave network unreachable, but our mapping would give unsupported...
		// For ftp, Go gives "unsupported protocol scheme \"ftp\"", original gives "proto error..."? Hmm. We'll map ftp to network unreachable to match?
		// Actually ftp test was with proxy? Let's just return s for now.
		return s
	}
	// Default: return original string truncated? Original error strings are short. We'll return s but replace newlines?
	// For DNS errors like "no such host", return as is?
	return s
}

func buildTransport(cfg *Config) (*http.Transport, error) {
	// TLS config
	tlsCfg := &tls.Config{
		InsecureSkipVerify: cfg.Insecure,
	}
	if cfg.Cacert != nil {
		data, err := os.ReadFile(*cfg.Cacert)
		if err != nil {
			return nil, err
		}
		pool, err := x509.SystemCertPool()
		if err != nil {
			pool = x509.NewCertPool()
		}
		if pool == nil {
			pool = x509.NewCertPool()
		}
		if !pool.AppendCertsFromPEM(data) {
			// Original with invalid cacert? What happens? Probably error. We'll return error.
			return nil, fmt.Errorf("failed to parse cacert")
		}
		tlsCfg.RootCAs = pool
	}
	if cfg.Cert != nil && cfg.Key != nil {
		_, err1 := os.ReadFile(*cfg.Cert)
		_, err2 := os.ReadFile(*cfg.Key)
		if err1 != nil { return nil, err1 }
		if err2 != nil { return nil, err2 }
		cert, err := tls.LoadX509KeyPair(*cfg.Cert, *cfg.Key)
		if err != nil {
			// Original panics with NoItemsFound for invalid content. We'll return error to be mapped?
			// To mimic panic, we could panic? But better return error.
			return nil, err
		}
		tlsCfg.Certificates = []tls.Certificate{cert}
	}
	// Proxy
	var proxyFunc func(*http.Request) (*url.URL, error)
	if cfg.Proxy != nil {
		pu, err := url.Parse(*cfg.Proxy)
		if err != nil {
			return nil, err
		}
		proxyFunc = http.ProxyURL(pu)
	}
	// DialContext with connect-timeout, connect-to, unix-socket, ipv
	dialer := &net.Dialer{
		Timeout: cfg.ConnectTimeout,
	}
	// Determine network
	network := "tcp"
	if cfg.Ipv4 && !cfg.Ipv6 {
		network = "tcp4"
	} else if cfg.Ipv6 && !cfg.Ipv4 {
		network = "tcp6"
	}
	// Parse connect-to mappings
	type mapping struct{host, port, targetHost, targetPort string}
	var mappings []mapping
	for _, s := range cfg.ConnectTo {
		parts := strings.Split(s, ":")
		if len(parts)==4 {
			mappings = append(mappings, mapping{parts[0],parts[1],parts[2],parts[3]})
		}
	}
	dialContext := func(ctx context.Context, netw, addr string) (net.Conn, error) {
		// unix socket?
		if cfg.UnixSocket != nil {
			// Only for non-HTTPS? Caller ensures? We'll check addr? For unix, ignore addr and dial unix
			// Need to determine if original URL is https: if https with unix, what? Original says only for non-HTTPS. We'll handle in request: if https and unix, return error directly, not here.
			return dialer.DialContext(ctx, "unix", *cfg.UnixSocket)
		}
		// connect-to override: addr is host:port
		host, port, err := net.SplitHostPort(addr)
		if err == nil {
			// Find matching mappings: host:port matches mapping host:port?
			// Original: strings like 'example.org:443:localhost:8443', if used several times for same host:port, random choice
			var candidates []mapping
			for _, m := range mappings {
				if m.host==host && m.port==port {
					candidates = append(candidates, m)
				}
			}
			if len(candidates)>0 {
				chosen := candidates[rand.Intn(len(candidates))]
				addr = net.JoinHostPort(chosen.targetHost, chosen.targetPort)
			}
		}
		return dialer.DialContext(ctx, network, addr)
	}
	tr := &http.Transport{
		Proxy: proxyFunc,
		DialContext: dialContext,
		DisableKeepAlives: cfg.DisableKeepalive,
		DisableCompression: cfg.DisableCompress,
		TLSClientConfig: tlsCfg,
		MaxIdleConnsPerHost: 1000,
		MaxIdleConns: 1000,
		IdleConnTimeout: 90 * time.Second,
	}
	// For unix socket, need to override DialTLS? For https+unix not supported, we already handle.
	return tr, nil
}

func buildBody(cfg *Config) (bodyBytes []byte, contentType string, isForm bool, boundary string, err error) {
	if len(cfg.Forms) > 0 {
		boundary = fmt.Sprintf("----formdata-oha-%x", rand.Uint64()<<32|uint64(rand.Uint32()))
		// Actually need 32 hex chars (16 bytes). rand.Uint64 gives 16 hex, need 32. Generate 16 bytes.
		b := make([]byte, 16)
		rand.Read(b)
		boundary = fmt.Sprintf("----formdata-oha-%x", b)
		var buf bytes.Buffer
		for _, f := range cfg.Forms {
			// Parse name=value or file=@path
			eq := strings.Index(f, "=")
			if eq == -1 {
				// Treat as name with empty value? Original? We'll treat as error? But just use as value?
				err = fmt.Errorf("invalid form")
				return
			}
			name := f[:eq]
			value := f[eq+1:]
			if strings.HasPrefix(value, "@") {
				// file
				fpath := value[1:]
				// Handle ;type=... suffix? e.g., file=@path;type=text/plain
				// Split by ;
				fpathOnly := fpath
				var ctype string
				if idx := strings.Index(fpath, ";"); idx != -1 {
					fpathOnly = fpath[:idx]
					// parse type? ignore for now, but extract?
					rest := fpath[idx+1:]
					if strings.HasPrefix(rest, "type=") {
						ctype = rest[5:]
					}
				}
				data, e := os.ReadFile(fpathOnly)
				if e != nil {
					err = e
					return
				}
				filename := filepath.Base(fpathOnly)
				buf.WriteString("--" + boundary + "\r\n")
				if ctype != "" {
					fmt.Fprintf(&buf, "Content-Disposition: form-data; name=\"%s\"; filename=\"%s\"\r\nContent-Type: %s\r\n\r\n", name, filename, ctype)
				} else {
					fmt.Fprintf(&buf, "Content-Disposition: form-data; name=\"%s\"; filename=\"%s\"\r\n\r\n", name, filename)
				}
				buf.Write(data)
				buf.WriteString("\r\n")
			} else {
				buf.WriteString("--" + boundary + "\r\n")
				fmt.Fprintf(&buf, "Content-Disposition: form-data; name=\"%s\"\r\n\r\n", name)
				buf.WriteString(value)
				buf.WriteString("\r\n")
			}
		}
		buf.WriteString("--" + boundary + "--\r\n")
		bodyBytes = buf.Bytes()
		contentType = "multipart/form-data; boundary=" + boundary
		isForm = true
		return
	}
	if cfg.BodyString != nil {
		bodyBytes = []byte(*cfg.BodyString)
	}
	if cfg.BodyPath != nil {
		data, e := os.ReadFile(*cfg.BodyPath)
		if e != nil {
			err = e
			return
		}
		bodyBytes = data
	}
	// BodyLines handled separately per-request (each request picks next line)
	return
}

