{"command": "cat >> /workspace/main.go <<'GO'

func doSingleRequestWithContext(client *http.Client, cfg *Config, urlStr string, bodyBytes []byte, formCT string, parentCtx context.Context, deadline time.Time, shouldWait bool) (status int, headers http.Header, body []byte, dnsLookup, dnsDialup, duration time.Duration, reqStart time.Time, errStr string, ver string) {
	httpVer := "1.1"
	if cfg.Http2 { httpVer = "2" } else if cfg.HttpVersion != nil { httpVer = *cfg.HttpVersion }
	if httpVer == "0.9" {
		return 0, nil, nil, 0, 0, 0, time.Now(), "dispatch task is gone", "HTTP/0.9"
	}
	if httpVer == "2" {
		u, e := url.Parse(urlStr)
		if e == nil && u.Scheme == "http" {
			return 0, nil, nil, 0, 0, 0, time.Now(), "http2 error", "HTTP/2"
		}
	}
	method := cfg.Method
	if len(cfg.Forms) > 0 && method == "GET" {
		method = "POST"
	}
	var bodyReader io.Reader
	if len(cfg.Forms) > 0 {
		bodyReader = bytes.NewReader(bodyBytes)
	} else if bodyBytes != nil {
		bodyReader = bytes.NewReader(bodyBytes)
	}
	req, err := http.NewRequest(method, urlStr, bodyReader)
	if err != nil {
		return 0, nil, nil, 0, 0, 0, time.Now(), mapError(err), "HTTP/1.1"
	}
	if httpVer == "1.0" {
		req.Proto = "HTTP/1.0"; req.ProtoMajor=1; req.ProtoMinor=0
	} else if httpVer == "1.1" {
		req.Proto = "HTTP/1.1"; req.ProtoMajor=1; req.ProtoMinor=1
	} else if httpVer == "2" {
		req.Proto = "HTTP/2"; req.ProtoMajor=2; req.ProtoMinor=0
	}
	buildRequestHeaders(cfg, req, len(bodyBytes))
	if len(cfg.Forms) > 0 {
		req.Header.Set("Content-Type", formCT)
	}
	var dnsStart, dnsDone, connStart, connDone time.Time
	var dnsDur, connDur time.Duration
	trace := &httptrace.ClientTrace{
		DNSStart: func(info httptrace.DNSStartInfo) { dnsStart = time.Now() },
		DNSDone: func(info httptrace.DNSDoneInfo) { dnsDone = time.Now(); if !dnsStart.IsZero() { dnsDur = dnsDone.Sub(dnsStart) } },
		ConnectStart: func(network, addr string) { connStart = time.Now() },
		ConnectDone: func(network, addr string, err error) { connDone = time.Now(); if !connStart.IsZero() { connDur = connDone.Sub(connStart) } },
	}
	// Context handling
	ctx := parentCtx
	if ctx == nil {
		ctx = context.Background()
	}
	// If not waiting, apply deadline to ctx
	if !shouldWait {
		// Use deadline as timeout
		var cancel context.CancelFunc
		ctx, cancel = context.WithDeadline(ctx, deadline)
		defer cancel()
	}
	// Also apply per-request timeout if set (take minimum)
	if cfg.Timeout != nil {
		var cancel2 context.CancelFunc
		ctx, cancel2 = context.WithTimeout(ctx, *cfg.Timeout)
		defer cancel2()
	}
	ctx = httptrace.WithClientTrace(ctx, trace)
	req = req.WithContext(ctx)
	reqStart = time.Now()
	resp, err := client.Do(req)
	duration = time.Since(reqStart)
	if err != nil {
		// Check if due to global deadline abort (not per-request timeout)
		if !shouldWait && time.Now().After(deadline.Add(-50*time.Millisecond)) {
			// If error is context deadline/canceled and request started before deadline, count as aborted
			ls := strings.ToLower(err.Error())
			if strings.Contains(ls, "deadline") || strings.Contains(ls, "canceled") || strings.Contains(ls, "cancel") {
				return 0, nil, nil, dnsDur, dnsDur+connDur, duration, reqStart, "aborted due to deadline", "HTTP/1.1"
			}
		}
		msg := mapError(err)
		if ue, ok := err.(*url.Error); ok {
			if strings.Contains(strings.ToLower(ue.Err.Error()), "stopped after") {
				msg = "Redirection limit has reached"
			}
		}
		if cfg.Timeout != nil && (strings.Contains(strings.ToLower(err.Error()), "deadline") || strings.Contains(strings.ToLower(err.Error()), "timeout")) {
			// Distinguish abort vs timeout: if abort case and after deadline, already handled above. Else timeout.
			// If shouldWait false and after deadline, it's abort, else timeout.
			// Already handled abort, so here it's timeout.
			msg = "timeout"
		}
		return 0, nil, nil, dnsDur, dnsDur+connDur, duration, reqStart, msg, "HTTP/1.1"
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	ver = resp.Proto
	if ver=="" { ver="HTTP/1.1" }
	return resp.StatusCode, resp.Header, b, dnsDur, dnsDur+connDur, duration, reqStart, "", ver
}

func outputResults(cfg *Config, stats *Stats, totalTime time.Duration) {
	format := cfg.OutputFormat
	var outWriter io.Writer = os.Stdout
	var outFile *os.File
	if cfg.Output != nil {
		f, err := os.Create(*cfg.Output)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %s\n", err.Error())
			os.Exit(1)
		}
		defer f.Close()
		outWriter = f
		outFile = f
		_ = outFile
	}
	switch format {
	case "quiet":
		// No output
	case "json":
		obj := buildJSON(stats, totalTime, cfg.StatsBreakdown)
		enc := json.NewEncoder(outWriter)
		enc.SetEscapeHTML(false)
		// Original json is pretty printed with 2 spaces? Our earlier capture shows 2-space indent. json.Encoder without indent gives compact. Need to use MarshalIndent.
		data, _ := json.MarshalIndent(obj, "", "  ")
		fmt.Fprintln(outWriter, string(data))
	case "csv":
		fmt.Fprintln(outWriter, "request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status")
		// Sort by start?
		sort.Slice(stats.CSVRows, func(i,j int) bool { return stats.CSVRows[i].Start < stats.CSVRows[j].Start })
		for _, r := range stats.CSVRows {
			fmt.Fprintf(outWriter, "%f,%f,%f,%f,%f,%d,%d\n", r.Start, r.DNS, r.DNSDialup, r.Delay, r.Duration, r.Bytes, r.Status)
		}
	case "text":
		// Need to handle breakdown: printTextOutput already handles breakdown via stats.Succ/NotSucc
		printTextOutput(stats, totalTime, cfg.TimeUnit, cfg.StatsBreakdown, outWriter)
	default:
		printTextOutput(stats, totalTime, cfg.TimeUnit, cfg.StatsBreakdown, outWriter)
	}
	// Handle gzip? No.
	// Handle db-url? Ignore (original didn't create file for our test, so ignore)
}

GO
"}

